{["evidence"]={["candidateID"]="athena-research-2026-10-27-07:catalog-unit-2921:history",["currentForeverAvailabilityVerified"]=false,["evidenceLocator"]="4063:description:1-24; 4063:description:114-206; 4063:description:208-268; 4063:description:26-60; 4063:description:273-331; 4063:description:62-79; 4063:description:81-109",["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["personalExperienceProven"]=false,["questSourceProofs"]={{["atomIDs"]={"4063:description:1-24","4063:description:114-206","4063:description:208-268","4063:description:26-60","4063:description:273-331","4063:description:62-79","4063:description:81-109"},["minimumStage"]=2,["questID"]=4063,["sourceHash"]="6451270ea6303df5adc4c4d1a7635a784e28382ebebcc9ea109891a5109907f2"}},["questSourceProofsMode"]="ALL",["sourceEra"]="RETAINED_QUESTDB_REFERENCE",["sourceIDs"]={"WARDEN-QUEST-4063"},["truthScope"]="QUEST_SOURCE_ACCOUNT"},["expected"]="UNKNOWN",["field"]="history",["gate"]="DISCOVERY",["id"]="catalog-unit-2921",["kind"]="figure",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="athena-research-01-10-2026-10-27",["text"]="Lotwil claimed he had killed Argelmach ten years earlier after the dwarf twisted his life’s work toward destructive ends; the new markings made him question that conclusion.",["title"]="Lotwil Veriatus"},
{["evidence"]={["candidateID"]="athena-research-2026-10-27-07:catalog-unit-2921:context",["currentForeverAvailabilityVerified"]=false,["evidenceLocator"]="778:description:13-34; 778:description:178-223; 778:description:39-56; 778:description:58-74; 778:description:7-11; 778:description:79-173",["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["personalExperienceProven"]=false,["questSourceProofs"]={{["atomIDs"]={"778:description:13-34","778:description:178-223","778:description:39-56","778:description:58-74","778:description:7-11","778:description:79-173"},["minimumStage"]=2,["questID"]=778,["sourceHash"]="1823f258104e81231337b579c345baedbf6e1f6bcd01ec4397a8e05249b1808c"}},["questSourceProofsMode"]="ALL",["sourceEra"]="RETAINED_QUESTDB_REFERENCE",["sourceIDs"]={"WARDEN-QUEST-778"},["truthScope"]="QUEST_SOURCE_ACCOUNT"},["expected"]="Type: Humanoid. Reported level: 36.",["field"]="context",["gate"]="DISCOVERY",["id"]="catalog-unit-2921",["kind"]="figure",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="athena-research-01-10-2026-10-27",["text"]="Lotwil presented the completed shackles as a combination of alchemy, engineering, and arcane practice, calling Lucien and Servo to witness his intended summoning.",["title"]="Lotwil Veriatus"},
{["evidence"]={["candidateID"]="athena-research-2026-10-27-07:catalog-unit-2921:outcome",["currentForeverAvailabilityVerified"]=false,["evidenceLocator"]="4063:completion:1-15; 4063:completion:123-234; 4063:completion:17-39; 4063:completion:41-121",["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["personalExperienceProven"]=false,["questSourceProofs"]={{["atomIDs"]={"4063:completion:1-15","4063:completion:123-234","4063:completion:17-39","4063:completion:41-121"},["minimumStage"]=4,["questID"]=4063,["sourceHash"]="6451270ea6303df5adc4c4d1a7635a784e28382ebebcc9ea109891a5109907f2"}},["questSourceProofsMode"]="ALL",["sourceEra"]="RETAINED_QUESTDB_REFERENCE",["sourceIDs"]={"WARDEN-QUEST-4063"},["truthScope"]="QUEST_SOURCE_ACCOUNT"},["expected"]="UNKNOWN",["field"]="outcome",["gate"]="DISCOVERY",["id"]="catalog-unit-2921",["kind"]="figure",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="athena-research-01-10-2026-10-27",["text"]="In the returned-head account, Lotwil judges the apparent Argelmach to be another dark-iron machine rather than flesh. He suspects a replacement may appear, rather than treating the destruction as a permanent end.",["title"]="Lotwil Veriatus"},
