{["evidence"]={["candidateID"]="athena-research-2026-10-27-07:catalog-unit-2922:context",["currentForeverAvailabilityVerified"]=false,["evidenceLocator"]="712:description:359-408; 712:description:410-467",["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["personalExperienceProven"]=false,["questSourceProofs"]={{["atomIDs"]={"712:description:359-408","712:description:410-467"},["minimumStage"]=2,["questID"]=712,["sourceHash"]="6119bf66b21fa5bc164c957533ee2e9691da97c79104835a2c1d350ecb598df6"}},["questSourceProofsMode"]="ALL",["sourceEra"]="RETAINED_QUESTDB_REFERENCE",["sourceIDs"]={"WARDEN-QUEST-712"},["truthScope"]="QUEST_SOURCE_ACCOUNT"},["expected"]="Type: Mechanical. Reported level: 5.",["field"]="context",["gate"]="DISCOVERY",["id"]="catalog-unit-2922",["kind"]="creature",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="athena-research-01-10-2026-10-27",["text"]="Lotwil blamed Servo for misplacing reagents and research, giving that as the reason he wanted spare bracers of rock binding.",["title"]="Servo"},
